style.css:
@-moz-document url-prefix("https://www.team-bhp.com/forum/") {
/* Post Content Width */

div[id^="content"] { 
    max-width: 1200px;
    width: 90%; /* responsive on smaller screens */
    margin: 0 auto;
    padding: 0 20px; /* breathing room on mobile */
    box-sizing: border-box;
}

/* Fonts */

div[id^="post"] {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Inter', 'Roboto', 'Helvetica Neue', Arial, sans-serif !important;
    line-height: 1.5;
    color: #000;
} 

div[id^="post_message_"] a {
    color: #E70106 !important;
    text-decoration: none;
    transition: color 0.2s ease !important;
}

div[id^="post_message_"] a:hover {
    color: #680f09 !important;
    text-decoration: underline !important;
}

div[id^="postmenu"] {
    font-weight: 500;
}
}
